// Partie 1 : le header. Il annonce l'algorithme de signature et le type.
{
  "alg": "HS256",
  "typ": "JWT"
}

// Partie 2 : le payload et ses claims. Tout ceci est LISIBLE par tous.
// Ne jamais y placer de mot de passe ou de donnee sensible.
{
  "iss": "https://auth.skillforge.local",
  "sub": "a3f1c7e2-9b4d-7a10-8c55-2e6f0b1d4a9c",
  "aud": "skillforge-api",
  "iat": 1717500000,
  "exp": 1717500900,
  "role": "apprenant"
}

// Partie 3 : la signature, calculee sur les deux parties ci-dessus
// avec la cle secrete. Elle n'est pas du JSON, c'est une empreinte.

// On s'appuie sur une bibliotheque eprouvee, jamais sur du code maison.
const jwt = require('jsonwebtoken')

function verifierJeton(token) {
  // Les options ci-dessous imposent les controles de securite.
  return jwt.verify(token, process.env.JWT_SECRET, {
    // On FIXE l'algorithme attendu cote serveur.
    // On ignore le champ alg du jeton : ni none, ni confusion possible.
    algorithms: ['HS256'],
    // Le jeton doit etre destine a notre API.
    audience: 'skillforge-api',
    // Le jeton doit venir de notre emetteur.
    issuer: 'https://auth.skillforge.local'
    // La signature et l'expiration (exp) sont verifiees automatiquement :
    // verify leve une erreur si la signature est invalide ou le jeton expire.
  })
}

// Middleware : on refuse proprement toute requete sans jeton valide.
function requireAuth(req, res, next) {
  const entete = req.headers.authorization || ''
  const token = entete.startsWith('Bearer ') ? entete.slice(7) : null
  if (!token) return res.status(401).json({ error: 'Authentification requise' })
  try {
    req.user = verifierJeton(token)
    next()
  } catch (e) {
    // On ne renvoie pas le detail de l'erreur au client.
    return res.status(401).json({ error: 'Jeton invalide' })
  }
}

Le code de validation suivant est dangereux. Trouve au moins deux problèmes de sécurité, explique-les, puis propose une version corrigée.

```javascript
const jwt = require('jsonwebtoken')

function verifierJeton(token) {
  // On lit l'algorithme directement depuis le jeton recu
  const header = JSON.parse(
    Buffer.from(token.split('.')[0], 'base64').toString()
  )
  return jwt.verify(token, process.env.JWT_SECRET, {
    algorithms: [header.alg]
  })
}
```

sections.solution:
**Problème 1, le plus grave : l'algorithme est pris dans le jeton lui-même.** La ligne `algorithms: [header.alg]` fait confiance au champ `alg` fourni par l'appelant. Un attaquant peut envoyer `alg: none` (jeton non signé accepté) ou provoquer une confusion d'algorithme en passant de `RS256` à `HS256` pour signer un faux jeton avec la clé publique. Il ne faut jamais déduire l'algorithme du jeton, il faut le **fixer côté serveur**.

**Problème 2 : ni `audience` ni `issuer` ne sont vérifiés.** Un jeton valide émis pour un autre service, ou par un émetteur non reconnu, serait accepté par notre API.

**Version corrigée :**
```javascript
const jwt = require('jsonwebtoken')

function verifierJeton(token) {
  // L'algorithme est impose cote serveur, pas lu dans le jeton.
  return jwt.verify(token, process.env.JWT_SECRET, {
    algorithms: ['HS256'],
    audience: 'skillforge-api',
    issuer: 'https://auth.skillforge.local'
  })
}
```
La signature et l'expiration restent vérifiées automatiquement par `verify`, qui lève une erreur à capturer pour répondre `401` sans fuite de détail.
